    with open(out, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow(["id", "ubicacion", "texto_minimo", "tipo", "fuente_y_metodo", "estado", "limitacion", "accion_recomendada"])
        w.writerows(R)
    from collections import Counter
